struct Approx {
    value: f64,
    epsilon: f64,
    scale: f64,
}

impl Approx {
    fn new(value: f64) -> Self {
        Self {
            value,
            epsilon: 1e-12,
            scale: 1.0,
        }
    }

    fn epsilon(mut self, epsilon: f64) -> Self {
        self.epsilon = epsilon;
        self
    }

    fn scale(mut self, scale: f64) -> Self {
        self.scale = scale;
        self
    }
}

impl PartialEq<f64> for Approx {
    fn eq(&self, other: &f64) -> bool {
        let diff = (self.value - other).abs();
        diff < self.epsilon * (self.scale + self.value.abs().max(other.abs()))
    }
}

impl PartialEq<Approx> for f64 {
    fn eq(&self, other: &Approx) -> bool {
        other.eq(self)
    }
}

